<script>
(()=>{const $=id=>document.getElementById(id),n=id=>parseFloat($(id).value);function npv(rate,arr){const d0=arr[0].d;return arr.reduce((s,x)=>s+x.v/Math.pow(1+rate,(x.d-d0)/86400000/365),0)}function xirr(arr){let grid=[];for(let x=-0.9999;x<=10;x+=x<1?0.02:0.2)grid.push(x);grid.push(20,50,100,250,500,1000);let a=null,b=null,fa=null;for(const r of grid){const f=npv(r,arr);if(!Number.isFinite(f))continue;if(f===0)return r;if(fa!==null&&f*fa<0){a=prev;b=r;break;}prev=r;fa=f;}if(a===null)return null;let l=a,h=b,fl=npv(l,arr);for(let i=0;i<160;i++){const m=(l+h)/2,fm=npv(m,arr);if(Math.abs(fm)<1e-8)return m;if(fl*fm<=0){h=m}else{l=m;fl=fm}}return(l+h)/2}
function go(){const s=n('start'),e=n('end'),y=n('years');if(Number.isFinite(s)&&Number.isFinite(e)&&Number.isFinite(y)&&s>0&&e>=0&&y>0){const c=Math.pow(e/s,1/y)-1;$('cagr').textContent=(c*100).toFixed(2)+'%';$('growth').textContent=((e/s-1)*100).toFixed(2)+'%';$('multiple').textContent=(e/s).toFixed(3)+'×'}else{$('cagr').textContent=$('growth').textContent=$('multiple').textContent='—'}let arr=[],bad=false;for(const line of $('flows').value.split(/\n+/)){if(!line.trim())continue;const p=line.split(',');if(p.length<2){bad=true;continue}const d=new Date(p[0].trim()+'T00:00:00Z'),v=parseFloat(p.slice(1).join(',').trim());if(!Number.isFinite(d.getTime())||!Number.isFinite(v)){bad=true;continue}arr.push({d:d.getTime(),v});}arr.sort((a,b)=>a.d-b.d);$('count').textContent=arr.length.toString();$('net').textContent=arr.reduce((s,x)=>s+x.v,0).toLocaleString(undefined,{maximumFractionDigits:2});if(arr.length<2||!arr.some(x=>x.v<0)||!arr.some(x=>x.v>0)){$('xirr').textContent='—';$('note').textContent='XIRR needs at least one negative and one positive dated cash flow.';$('note').className='helper danger';return;}const r=xirr(arr);$('xirr').textContent=r===null?'No root found':(r*100).toFixed(3)+'%';$('note').textContent=(bad?'Some malformed lines were ignored. ':'')+(r===null?'The cash-flow pattern may have no XIRR in the search range or may have multiple roots.':'XIRR is the annualized rate that makes the dated cash flows have approximately zero net present value using a 365-day year.');$('note').className='helper'+((bad||r===null)?' danger':'');}
['start','end','years','flows'].forEach(id=>$(id).addEventListener('input',go));$('calc').onclick=go;$('reset').onclick=()=>{$('start').value=100000;$('end').value=150000;$('years').value=3;$('flows').value='2023-01-01,-100000\n2023-09-15,-20000\n2024-07-01,30000\n2026-01-01,140000';go();};go();})();
</script>
